import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('drug-induced-blistering',
  kf=["**SJS/TEN** are severe drug reactions with widespread keratinocyte death: **SJS <10%**, overlap 10–30%, **TEN >30%** body surface detachment.",
      "Prodrome of fever and sore eyes/throat, then painful dusky macules, atypical flat targets, blisters, **Nikolsky sign** and **≥2 mucosal sites**.",
      "Culprits started **4–28 days** earlier: allopurinol, aromatic anticonvulsants, lamotrigine, sulfonamides (co-trimoxazole), nevirapine, oxicam NSAIDs.",
      "Stop all non-essential drugs; **999 / same-day** transfer to a burns or dermatology intensive unit; ophthalmology within 24 h.",
      "SCORTEN predicts mortality (about 10% in SJS, 30%+ in TEN); record the allergy and Yellow Card."],
  epi=[{"t": "**Who**", "sub": ["Rare (1–6 per million per year); higher risk with HIV, lupus, cancer and HLA-B*15:02 (carbamazepine in South-East Asian people)."]}],
  myths=["**\"Blisters on lips and eyes are just cold sores\"**: mucositis with a new drug and skin pain is SJS until proven otherwise."],
  patho_lead="Drug-specific **cytotoxic T cells** trigger mass **keratinocyte apoptosis**, so the whole epidermis peels away.",
  mech=[("Drug–HLA presentation", "The drug binds specific HLA molecules and activates CD8+ T cells and NK cells."),
        ("Cytotoxic mediators", "Granulysin, perforin/granzyme and Fas–FasL kill keratinocytes."),
        ("Full-thickness necrosis", "The entire epidermis dies and separates from the dermis.", "v4-ten-necrosis.jpg", "Normal skin (left) versus toxic epidermal necrolysis (right): full-thickness epidermal necrosis detaching as a sheet with sparse dermal inflammation."),
        ("Mucosal involvement", "Eyes, mouth, genitals and airway are affected the same way, causing scarring.")],
  histo=["Full-thickness epidermal necrosis with sparse dermal inflammation; frozen section can distinguish from SSSS (split high in epidermis)."],
  special=[{"t": "**Children**", "sub": ["Mycoplasma causes mucositis-predominant disease (MIRM); also consider SSSS (painful red skin, superficial peeling, mucosa spared)."]}],
  comp=["Sepsis, fluid loss, respiratory failure; eye scarring and blindness, strictures, nail and hair loss, pigmentation; death."],
  prog=["Mortality depends on SCORTEN; survivors often have long-term eye and skin problems."],
  see_also=["fixed-drug-eruption", "agep", "dress", "erythema-multiforme", "drug-eruption-approach"])

E('dermatomyositis',
  kf=["**Dermatomyositis** is an autoimmune disease of skin and muscle: **heliotrope** eyelids, **Gottron papules**, shawl and V signs, nailfold changes.",
      "Proximal muscle weakness (may be absent: amyopathic DM); check CK, myositis antibodies, ANA.",
      "Adults: strongly linked to **cancer** (ovary, lung, breast, GI, nasopharynx): screen at diagnosis and for 3 years.",
      "Anti-MDA5 disease: rapidly progressive interstitial lung disease and skin ulcers.",
      "Specialist treatment: photoprotection, steroids, steroid-sparing agents (methotrexate, MMF), IVIG, hydroxychloroquine for skin."],
  epi=[{"t": "**Who**", "sub": ["Two peaks: children 5–15 and adults 40–60; women twice as often."]}],
  myths=["**\"Normal CK excludes dermatomyositis\"**: amyopathic disease has typical skin signs with normal muscles."],
  patho_lead="DM is an **interferon-driven attack** on small blood vessels in skin and muscle.",
  mech=[("Autoantibodies", "Myositis-specific antibodies (Mi-2, TIF1-γ, NXP2, MDA5) mark subtypes and cancer risk."),
        ("Type I interferon", "Interferon signatures drive inflammation and complement activation."),
        ("Capillary damage", "Complement destroys capillaries (nailfold dilated loops, muscle perifascicular atrophy)."),
        ("Photosensitive interface dermatitis", "UV-exposed skin shows violaceous erythema (shawl, V sign).")],
  histo=["Interface dermatitis with dermal mucin (like lupus); muscle biopsy: perifascicular atrophy."],
  special=[{"t": "**Juvenile DM**", "sub": ["Calcinosis and vasculopathy; no cancer link."]}],
  comp=["Cancer, interstitial lung disease, dysphagia, aspiration, calcinosis, cardiac involvement."],
  prog=["Chronic; survival depends on cancer and lung disease."],
  see_also=["discoid-lupus", "lung-cancer-skin-signs", "photoageing", "polymorphic-light-eruption"])

E('iga-vasculitis',
  kf=["**IgA vasculitis** (Henoch–Schönlein purpura) is the commonest childhood vasculitis: **palpable purpura** on the buttocks and legs.",
      "Tetrad: purpura, arthralgia/arthritis, abdominal pain (intussusception risk) and **renal involvement** (haematuria, proteinuria).",
      "Often follows an upper respiratory infection; ages 3–10.",
      "First exclude **meningococcal sepsis** in an unwell child with a non-blanching rash.",
      "Supportive care; monitor **urine and BP** for 6–12 months; adults have more renal disease."],
  epi=[{"t": "**Who**", "sub": ["About 20 per 100,000 children per year; autumn and winter; adults less often but more severely."]}],
  myths=["**\"The rash settled, so follow-up can stop\"**: nephritis can appear weeks to months later."],
  patho_lead="Abnormal **IgA1** forms immune complexes that lodge in small vessels.",
  mech=[("Abnormal IgA1", "Galactose-deficient IgA1 is produced after a mucosal infection."),
        ("Immune complexes", "IgA complexes deposit in small vessel walls in skin, gut, joints and kidney."),
        ("Leukocytoclastic vasculitis", "Neutrophils damage vessels and red cells leak: palpable purpura.", "v4-lcv-vessel.jpg", "Small-vessel vasculitis: immune complexes on the vessel wall attract neutrophils that fragment and damage it, letting red cells leak out (palpable purpura)."),
        ("Nephritis", "Mesangial IgA deposits cause haematuria and proteinuria.")],
  histo=["Leukocytoclastic vasculitis with IgA on direct IF of a new lesion."],
  comp=["Nephritis and chronic kidney disease, intussusception, orchitis."],
  prog=["Most children recover in 4–6 weeks; recurrence in a third."],
  see_also=["leukocytoclastic-vasculitis", "purpura-differentials", "cutaneous-vasculitis-approach", "urticarial-vasculitis"])

E('leukocytoclastic-vasculitis',
  kf=["**Cutaneous small-vessel (leukocytoclastic) vasculitis** presents as **palpable purpura** on the lower legs, often in crops.",
      "Causes: drugs, infection (strep, hepatitis B/C), autoimmune disease, malignancy; up to half idiopathic.",
      "Look for systemic disease: urine dipstick and BP, FBC, U&E, LFT, CRP, ANA, ANCA, complement, hepatitis serology, cryoglobulins.",
      "Biopsy an early lesion (<48 h) for histology and direct IF.",
      "Stop culprit drug, rest, elevation, compression; refer if systemic or recurrent."],
  epi=[{"t": "**Who**", "sub": ["Any age; adults most often."]}],
  myths=["**\"Purpura is always low platelets\"**: palpable purpura with normal platelets suggests vasculitis."],
  patho_lead="Immune complexes trigger **neutrophils to destroy small vessels**.",
  mech=[("Antigen", "A drug, infection or autoantigen forms immune complexes."),
        ("Deposition", "Complexes lodge in post-capillary venules, especially in dependent legs."),
        ("Neutrophil damage", "Complement attracts neutrophils that fragment (leukocytoclasis) and damage vessels.", "v4-lcv-vessel.jpg", "Immune complexes and fragmenting neutrophils damage the vessel wall; red cells leak out."),
        ("Purpura", "Red cells leak, causing raised purpura that does not blanch.")],
  histo=["Fibrinoid necrosis of small vessels, neutrophils with nuclear dust, red cell extravasation."],
  comp=["Ulceration; systemic vasculitis (kidney, gut, nerves)."],
  prog=["Single episodes settle in weeks; chronic forms recur."],
  see_also=["iga-vasculitis", "urticarial-vasculitis", "cutaneous-vasculitis-approach", "purpura-differentials", "polyarteritis-nodosa"])

E('urticarial-vasculitis',
  kf=["**Urticarial vasculitis** looks like urticaria, but wheals last **over 24 hours**, burn more than itch, and leave **bruising**.",
      "Normocomplementaemic (often skin-limited) or **hypocomplementaemic** (linked to lupus, systemic disease).",
      "Check C3, C4, C1q, ANA, urine, ESR/CRP; biopsy confirms vasculitis.",
      "Antihistamines help less than in urticaria; specialist options include dapsone, colchicine, hydroxychloroquine.",
      "Hypocomplementaemic UV: watch for lung (COPD), kidney and eye disease."],
  epi=[{"t": "**Who**", "sub": ["Uncommon; middle-aged women most; about 5% of chronic 'urticaria' cases."]}],
  myths=["**\"All wheals are urticaria\"**: wheals lasting over a day with bruising need biopsy."],
  patho_lead="Immune complexes cause **vasculitis** in vessels beneath a wheal.",
  mech=[("Immune complexes", "Complexes activate complement (low C3/C4/C1q in hypocomplementaemic disease)."),
        ("Mast cell and neutrophil activation", "C5a degranulates mast cells (wheal) and attracts neutrophils (vasculitis)."),
        ("Persistent lesion", "Vessel damage makes wheals last over 24 hours and leave purpura.", "v3-wheal-pen-circle.jpg", "Circling a wheal with a pen shows how long each lasts.")],
  histo=["Leukocytoclastic vasculitis beneath an urticarial lesion; DIF may show immunoglobulin and complement in vessels."],
  comp=["Angioedema, arthritis, glomerulonephritis, COPD, uveitis (hypocomplementaemic)."],
  prog=["Variable; may last years."],
  see_also=["urticaria-angioedema", "leukocytoclastic-vasculitis", "discoid-lupus", "cutaneous-vasculitis-approach"])

E('polyarteritis-nodosa',
  kf=["**Polyarteritis nodosa (PAN)** is a necrotising vasculitis of **medium-sized arteries**.",
      "Skin: tender subcutaneous nodules, **livedo racemosa**, ulcers, digital ischaemia; cutaneous PAN may be skin-limited.",
      "Systemic PAN: hypertension, renal infarcts, mononeuritis multiplex, abdominal pain, weight loss; **ANCA negative**.",
      "Associated with hepatitis B; deep incisional biopsy of a nodule needed.",
      "Specialist treatment: steroids ± cyclophosphamide; antivirals for HBV-PAN."],
  epi=[{"t": "**Who**", "sub": ["Rare; adults 40–60; children with cutaneous PAN after streptococcal infection."]}],
  myths=["**\"Normal ANCA excludes vasculitis\"**: PAN is ANCA-negative."],
  patho_lead="PAN inflames and destroys the **walls of medium arteries**, causing aneurysms and infarcts.",
  mech=[("Trigger", "Hepatitis B immune complexes or unknown triggers."),
        ("Transmural necrosis", "Fibrinoid necrosis of the full arterial wall at the dermo-subcutaneous junction."),
        ("Aneurysms and thrombosis", "Weakened walls balloon (microaneurysms); thrombosis causes infarction."),
        ("Livedo and ulcers", "Patchy arterial blockage gives broken livedo, nodules and ulcers.")],
  histo=["Necrotising arteritis of medium vessels in deep dermis/subcutis; deep biopsy required."],
  comp=["Renal failure, hypertension, bowel infarction, stroke, neuropathy."],
  prog=["Cutaneous PAN is chronic but benign; systemic PAN is serious but often remits with treatment."],
  see_also=["livedo-reticularis", "leukocytoclastic-vasculitis", "cutaneous-vasculitis-approach", "erythema-nodosum"])

E('livedo-reticularis',
  kf=["**Livedo reticularis** is a violaceous, net-like (reticulate) mottling of the skin from sluggish blood flow.",
      "Physiological (cold, complete regular rings, fades on warming) versus pathological (**livedo racemosa**: broken, irregular, persistent).",
      "Pathological causes: antiphospholipid syndrome, vasculitis (PAN), cholesterol emboli, cryoglobulins, calciphylaxis, drugs (amantadine).",
      "Investigate persistent or broken livedo: FBC, clotting, antiphospholipid antibodies, ANA, cryoglobulins, renal function.",
      "Livedo plus stroke: Sneddon syndrome (antiphospholipid)."],
  epi=[{"t": "**Who**", "sub": ["Physiological cutis marmorata common in infants and young women."]}],
  myths=["**\"Mottled skin is always harmless\"**: persistent, broken livedo may signal clotting or vasculitis."],
  patho_lead="Livedo appears when blood **pools in the venous network** at the edge of each skin perfusion cone.",
  mech=[("Perfusion cones", "Each arteriole supplies a cone of skin; the edges are drained by a venous plexus."),
        ("Slow flow", "Cold, spasm or blockage slows flow so deoxygenated blood pools at the cone edges: a violet net."),
        ("Racemosa", "Patchy arteriolar blockage (thrombosis, vasculitis) breaks the rings into irregular shapes.")],
  comp=["Depends on cause: ulceration, stroke, renal failure."],
  prog=["Physiological livedo is benign; pathological livedo follows its cause."],
  see_also=["polyarteritis-nodosa", "cutaneous-vasculitis-approach", "purpura-differentials", "endocarditis-skin-signs"])

E('purpura-differentials',
  kf=["**Purpura** is bleeding into the skin that does **not blanch**: petechiae (<2 mm), purpura (2–10 mm), ecchymoses (>1 cm).",
      "**Non-blanching rash in an unwell or febrile child: meningococcal sepsis until proven otherwise** (NICE NG240: benzylpenicillin, 999).",
      "Flat purpura: platelets, clotting, vessel fragility (steroids, age, scurvy); palpable purpura: vasculitis.",
      "Tests: FBC and film, clotting, U&E, LFT, CRP, blood cultures if febrile; urine and BP for vasculitis.",
      "Consider leukaemia (petechiae, pallor, bone pain), ITP, anticoagulants and non-accidental injury in children."],
  myths=["**\"The glass test is negative so it's fine\"**: early meningococcal rash may blanch; judge the whole child."],
  patho_lead="Purpura means **red cells outside vessels**: from low platelets, clotting defects, fragile or inflamed vessels.",
  mech=[("Platelet problem", "Low or dysfunctional platelets cause petechiae and mucosal bleeding."),
        ("Coagulation problem", "Clotting factor deficiency causes larger bruises and deep bleeds."),
        ("Vessel fragility", "Thin dermis (age, steroids) or weak collagen (scurvy) lets vessels tear: senile purpura."),
        ("Vasculitis", "Inflamed vessels leak red cells, causing raised palpable purpura.", "v4-lcv-vessel.jpg", "Vasculitis: neutrophils damage small vessels and red cells leak into the dermis.")],
  comp=["Depends on cause: sepsis, haemorrhage, organ damage."],
  prog=["Depends on cause."],
  see_also=["iga-vasculitis", "leukocytoclastic-vasculitis", "skin-fragility-dermatoporosis", "cutaneous-vasculitis-approach", "dengue"])

E('cutaneous-vasculitis-approach',
  kf=["**Vasculitis** is classified by vessel size: **small** (palpable purpura), **medium** (nodules, livedo racemosa, ulcers), **large** (rarely skin).",
      "Always ask: is it skin-limited or systemic? Check **urine dipstick and BP** in every patient.",
      "Biopsy an early lesion (<48 h) with direct IF; deep biopsy for medium-vessel disease.",
      "Screen: FBC, U&E, LFT, CRP, ANA, ANCA, complement, hepatitis B/C, HIV, cryoglobulins, immunoglobulins.",
      "Same-day: unwell, renal involvement, haemoptysis, neuropathy, gut ischaemia, or child with possible meningococcal disease."],
  myths=["**\"Skin vasculitis is just a rash\"**: it can be the first sign of kidney or lung disease."],
  patho_lead="Vasculitis is **inflammation of vessel walls**; the size of vessel decides what you see.",
  mech=[("Small vessels", "Immune complexes in post-capillary venules: palpable purpura, wheals.", "v4-lcv-vessel.jpg", "Small-vessel vasculitis with neutrophils and red-cell leakage."),
        ("Medium vessels", "Arteries at the dermo-subcutaneous junction: nodules, livedo racemosa, ulcers, digital infarcts."),
        ("ANCA vasculitis", "ANCA activate neutrophils against small–medium vessels (GPA, MPA, EGPA)."),
        ("Systemic spread", "The same process in kidney, lung, nerve and gut causes organ damage.")],
  comp=["Renal failure, pulmonary haemorrhage, neuropathy, gut infarction, ulcers."],
  prog=["Skin-limited forms usually settle; systemic vasculitis needs immunosuppression."],
  see_also=["leukocytoclastic-vasculitis", "iga-vasculitis", "urticarial-vasculitis", "polyarteritis-nodosa", "livedo-reticularis"])

E('porphyria-cutanea-tarda',
  kf=["**Porphyria cutanea tarda (PCT)** is the commonest porphyria: blisters, erosions, **skin fragility**, scars and **milia** on the backs of the hands.",
      "Also facial hypertrichosis and hyperpigmentation; urine may be dark.",
      "Triggers: **alcohol, oestrogens, hepatitis C, HIV, iron overload (haemochromatosis)**, smoking.",
      "Confirm: plasma and urine porphyrins; check ferritin, LFT, hepatitis C, HFE genotype.",
      "Specialist: venesection (iron reduction) or low-dose hydroxychloroquine; remove triggers; visible-light protection."],
  epi=[{"t": "**Who**", "sub": ["Adults over 40; about 1 in 10,000–25,000; familial form in about a fifth."]}],
  myths=["**\"Sunscreen protects\"**: ordinary sunscreens do not block the visible light (around 400 nm) that excites porphyrins."],
  patho_lead="Reduced activity of **uroporphyrinogen decarboxylase** in the liver lets **light-sensitive porphyrins** build up in the skin.",
  mech=[("Enzyme inhibition", "Iron and oxidative stress (alcohol, hepatitis C, oestrogen) inhibit hepatic UROD."),
        ("Porphyrin accumulation", "Uroporphyrins accumulate in the liver, blood and skin."),
        ("Phototoxicity", "Visible light (about 400–410 nm) excites porphyrins, generating reactive oxygen that damages the dermo-epidermal junction."),
        ("Fragility and blisters", "Minor trauma causes subepidermal blisters that heal with scars and milia.", "v4-milia-section.jpg", "Milia form as blisters heal: tiny keratin cysts just beneath the epidermis.")],
  histo=["Cell-poor subepidermal blister with 'festooning' of dermal papillae; caterpillar bodies."],
  special=[{"t": "**Pseudoporphyria**", "sub": ["Same skin signs with normal porphyrins: naproxen, tetracyclines, furosemide, sunbeds, dialysis."]}],
  comp=["Scarring, cirrhosis, hepatocellular carcinoma (in liver disease)."],
  prog=["Remits with iron depletion or hydroxychloroquine; relapse if triggers return."],
  see_also=["milia", "skin-fragility-dermatoporosis", "drug-photosensitivity", "epidermolysis-bullosa", "bullous-pemphigoid"])

E('drug-induced-pigmentation',
  kf=["Drugs cause about 10–20% of acquired hyperpigmentation; colours and sites are clues.",
      "**Minocycline**: blue-grey on scars, shins and sclera; **amiodarone**: slate-grey on sun-exposed face; **hydroxychloroquine**: grey-blue shins and palate.",
      "Chemotherapy (bleomycin flagellate streaks, 5-FU), zidovudine (nails), clofazimine (red-brown), heavy metals (argyria).",
      "Fixed drug eruption leaves round grey-brown patches at the same sites.",
      "Stop or switch the drug with the prescriber; pigmentation fades slowly (months–years) or may be permanent; photoprotection."],
  myths=["**\"It'll go as soon as the drug stops\"**: dermal pigment can persist for years."],
  patho_lead="Drugs pigment skin by **increasing melanin, depositing themselves, or forming drug–iron–melanin complexes**.",
  mech=[("Increased melanin", "Some drugs stimulate melanocytes (oral contraceptives in melasma, chemotherapy)."),
        ("Drug deposition", "Drug or metabolites deposit in the dermis (amiodarone lipofuscin, gold, silver)."),
        ("Complexes", "Drug, iron and melanin bind together in dermal macrophages (minocycline)."),
        ("Post-inflammatory", "Inflammatory reactions leave melanin in the dermis (fixed drug eruption).")],
  comp=["Cosmetic distress; marker of cumulative dose (amiodarone)."],
  prog=["Variable; laser may help some (minocycline)."],
  see_also=["fixed-drug-eruption", "melasma-facial-melanosis", "drug-photosensitivity", "contact-lichenoid-pigmentation", "addisons-disease"])
